import sys

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    a = list(map(int, input[1:n+1]))

    swaps = []
    for i in range(n):
        for j in range(i + 1, n):
            if a[i] > a[j]:
                swaps.append((i + 1, j + 1))
                a[i], a[j] = a[j], a[i]

    if a == sorted(a):
        print(len(swaps))
        for swap in swaps:
            print(swap[0], swap[1])
    else:
        print(-1)

if __name__ == "__main__":
    main()
